/**
 * ILLUSTRATIVE SAMPLE DATA — NOT OFFICIAL STATISTICS.
 *
 * These numbers are generated by simple formulas so the dashboard layout can be
 * shown before real data is connected. Periods are labelled "P1, P2, …" instead of
 * calendar dates on purpose, so nothing here can be mistaken for real history.
 */

export type Dataset = {
  id: string;
  title: string;
  description: string;
  unit: string;
  frequency: string;
  xLabel: string;
  kind: "timeseries" | "curve";
  series: { key: string; label: string }[];
  rows: Record<string, number | string>[];
  source: string;
  sourceUrl: string;
  /** When the data was fetched from its source. null for sample data. */
  retrievedAt: string | null;
  isSample: boolean;
};

const r2 = (n: number) => Math.round(n * 100) / 100;
const periods = Array.from({ length: 24 }, (_, i) => i + 1);

const SAMPLE_SOURCE = "Illustrative sample (synthetic numbers). Not official data.";

export const sampleDatasets: Dataset[] = [
  {
    id: "inflation-gdp",
    title: "Inflation and GDP growth",
    description: "Year-on-year consumer price inflation and real GDP growth.",
    unit: "% per year",
    frequency: "Quarterly (sample periods)",
    xLabel: "Period",
    kind: "timeseries",
    series: [
      { key: "inflation", label: "Inflation" },
      { key: "gdp", label: "GDP growth" },
    ],
    rows: periods.map((i) => ({
      x: `P${i}`,
      inflation: r2(5 + 1.5 * Math.sin(i / 3) + 0.04 * i),
      gdp: r2(6.5 + 1.2 * Math.cos(i / 4) - 0.02 * i),
    })),
    source: SAMPLE_SOURCE,
    sourceUrl: "",
    retrievedAt: null,
    isSample: true,
  },
  {
    id: "rates",
    title: "Policy rate and 10-year government bond yield",
    description: "The short-term policy rate against the long-term benchmark yield.",
    unit: "% per year",
    frequency: "Quarterly (sample periods)",
    xLabel: "Period",
    kind: "timeseries",
    series: [
      { key: "policy", label: "Policy rate" },
      { key: "yield10", label: "10-year yield" },
    ],
    rows: periods.map((i) => ({
      x: `P${i}`,
      policy: r2(5.5 + 0.8 * Math.sin(i / 6) + 0.02 * i),
      yield10: r2(6.9 + 0.5 * Math.sin(i / 5 + 0.6) + 0.015 * i),
    })),
    source: SAMPLE_SOURCE,
    sourceUrl: "",
    retrievedAt: null,
    isSample: true,
  },
  {
    id: "yield-curve",
    title: "Yield curve shapes",
    description: "Yield by maturity for two illustrative curve shapes: upward-sloping and nearly flat.",
    unit: "% per year",
    frequency: "Single snapshot (sample)",
    xLabel: "Maturity",
    kind: "curve",
    series: [
      { key: "upward", label: "Upward-sloping" },
      { key: "flat", label: "Nearly flat" },
    ],
    rows: [
      { x: "3M", upward: 6.1, flat: 6.8 },
      { x: "6M", upward: 6.2, flat: 6.8 },
      { x: "1Y", upward: 6.4, flat: 6.8 },
      { x: "2Y", upward: 6.6, flat: 6.9 },
      { x: "5Y", upward: 6.9, flat: 7.0 },
      { x: "10Y", upward: 7.1, flat: 7.0 },
      { x: "30Y", upward: 7.3, flat: 7.1 },
    ],
    source: SAMPLE_SOURCE,
    sourceUrl: "",
    retrievedAt: null,
    isSample: true,
  },
  {
    id: "market-index",
    title: "Equity market index (base = 100)",
    description: "A generic index level rebased to 100 at the first period. Not a real index.",
    unit: "Index points",
    frequency: "Quarterly (sample periods)",
    xLabel: "Period",
    kind: "timeseries",
    series: [{ key: "index", label: "Index level" }],
    rows: periods.map((i) => ({ x: `P${i}`, index: r2(100 + 3.2 * (i - 1) + 6 * Math.sin(i / 2)) })),
    source: SAMPLE_SOURCE,
    sourceUrl: "",
    retrievedAt: null,
    isSample: true,
  },
];

